def gen(rng):
    def fmt(n, z):
        return '%d\n%s' % (n, ' '.join(['0'] * z + ['1'] * (n - z)))
    tests = [fmt(1, 0), fmt(1, 1), fmt(2, 0), fmt(2, 1), fmt(2, 2), fmt(8, 3), fmt(10, 10), fmt(10, 0), fmt(10, 9)]
    for n in (3, 5, 8, 13, 20, 50, 100):
        for _ in range(2):
            tests.append(fmt(n, rng.randint(0, n)))
    N = 10**6
    tests.append(fmt(N, rng.randint(1, N - 1)))
    tests.append(fmt(N, N - 1))
    tests.append(fmt(N, N))
    return tests
